(function(){
  const list=document.querySelector(".pl"),prev=document.querySelector(".pl-prev");
  const rows=[...list.querySelectorAll(".pl-row")],shots=[...prev.querySelectorAll(".ph")];
  if(!matchMedia("(hover:hover)").matches)return;
  // quickTo נותן מעקב רך אחרי הסמן בלי ליצור טווין חדש בכל אירוע
  const xTo=gsap.quickTo(prev,"x",{duration:.55,ease:"power3"});
  const yTo=gsap.quickTo(prev,"y",{duration:.55,ease:"power3"});
  const w=()=>prev.offsetWidth,h=()=>prev.offsetHeight;
  let shown=false,placed=false;
  function place(e){
    // בעברית הסמן קורא ימינה-שמאלה, ולכן החלונית יושבת משמאל לסמן
    let x=e.clientX-w()-26;
    if(x<12)x=e.clientX+26;
    let y=gsap.utils.clamp(12,window.innerHeight-h()-12,e.clientY-h()/2);
    // המיקום הראשון נקבע מיידית, אחרת החלונית נפתחת בפינת המסך וטסה משם
    if(!placed){placed=true;gsap.set(prev,{x:x,y:y});}
    xTo(x);yTo(y);
  }
  list.addEventListener("pointermove",place);
  rows.forEach(r=>{
    r.addEventListener("pointerenter",()=>{
      rows.forEach(x=>x.classList.toggle("on",x===r));
      shots.forEach((s,i)=>s.classList.toggle("on",i===+r.dataset.i));
      if(!shown){
        shown=true;list.classList.add("hovering");
        gsap.to(prev,{opacity:1,scale:1,duration:.35,ease:"power3.out"});
      }
    });
  });
  list.addEventListener("pointerleave",()=>{
    shown=false;list.classList.remove("hovering");
    rows.forEach(x=>x.classList.remove("on"));
    gsap.to(prev,{opacity:0,scale:.94,duration:.25,ease:"power2.in"});
  });
})();

entries.css:
/* G45 · מפת סביבה: קו שנמתח עם תחנות ומרחקים */
html,body{overflow-x:clip}
.geo{padding:clamp(60px,8vw,120px) 0 clamp(80px,10vw,150px);background:#faf8f4}
.geo-head{text-align:center;padding-inline:var(--gutter, clamp(24px, 5vw, 96px));margin-bottom:clamp(30px,4vw,60px)}
.geo-head h3{font-size:clamp(28px,3.6vw,60px);margin:0 0 10px;font-weight:800}
.geo-head p{margin:0;color:var(--muted, #6a6d85)}
.geo-wrap{position:relative;width:min(1100px,94vw);margin-inline:auto}
.geo-wrap svg{width:100%;height:auto;overflow:visible;display:block}
.geo-line{fill:none;stroke:#16182b;stroke-width:2;stroke-linecap:round}
.geo-stop{position:absolute;transform:translate(-50%,-50%);text-align:center;opacity:0}
.geo-dot{width:11px;height:11px;border-radius:50%;background:#16182b;margin-inline:auto;position:relative}
.geo-dot::after{content:"";position:absolute;inset:-7px;border-radius:50%;border:1px solid rgba(22,24,43,.28)}
.geo-name{font-size:clamp(13px,1.1vw,16px);font-weight:700;margin-top:12px;white-space:nowrap}
.geo-min{font-size:12px;color:var(--muted, #6a6d85);letter-spacing:.06em;white-space:nowrap}
.geo-home{position:absolute;transform:translate(-50%,-50%);text-align:center}
.geo-home .geo-dot{width:16px;height:16px;background:#c2255c}
.geo-home .geo-name{color:#c2255c}
@media(max-width:767px){.geo-name{font-size:12px}.geo-min{font-size:11px}}

entries.js:
gsap.registerPlugin(ScrollTrigger, DrawSVGPlugin);

(function(){
  const stops=gsap.utils.toArray(".geo-stop");
  gsap.set(stops,{opacity:0,y:14});
  const tl=gsap.timeline({scrollTrigger:{trigger:".geo-wrap",start:"top 78%",end:"bottom 62%",scrub:.8}});
  // הקו נמתח מהקצה הימני שמאלה, ככיוון הקריאה: ה-path מוגדר כך שנקודת ההתחלה שלו בימין
  tl.fromTo("#geoPath",{drawSVG:"0% 0%"},{drawSVG:"0% 100%",ease:"none",duration:1},0);
  // כל תחנה נדלקת ברגע שהקו עובר לידה
  stops.forEach(s=>{
    tl.to(s,{opacity:1,y:0,duration:.12,ease:"back.out(2)"},+s.dataset.p);
  });
})();

