.vback{font-size:14px;font-weight:500;color:var(--muted, #6a6d85);border:1px solid var(--line, #e4e4ee);border-radius:999px;padding:7px 16px;background:#fff;text-decoration:none;transition:color .18s,border-color .18s}
.vback:hover{color:var(--accent, #4a3aff);border-color:var(--accent, #4a3aff)}

/* R10 · CircularGallery: גלריה מסלולית WebGL */
.rload{display:flex;gap:10px;flex-wrap:wrap;align-items:center;padding-inline:var(--gutter, clamp(24px, 5vw, 96px));margin-bottom:16px}
.rframe{display:none;border-block:1px solid var(--line, #e4e4ee);background:#0e0f1a}
.rframe.on{display:block}
.rframe iframe{width:100%;height:min(82vh,780px);border:0;display:block}
.rinstall{padding-inline:var(--gutter, clamp(24px, 5vw, 96px))}
.rinstall code{font-size:12.5px;background:#ececf4;border:1px solid var(--line, #e4e4ee);border-radius:8px;padding:8px 14px;direction:ltr;display:inline-block;max-width:100%;overflow-x:auto;white-space:nowrap}
.rdeps{font-size:13px;color:var(--muted, #6a6d85);padding:8px var(--gutter, clamp(24px, 5vw, 96px)) 0}

entries.js:
const btn=document.querySelector(".rbtn"),wrap=document.querySelector(".rframe");
btn.addEventListener("click",()=>{
  if(wrap.classList.contains("on")){wrap.classList.remove("on");wrap.innerHTML="";btn.textContent="טען דמו חי כאן";return;}
  wrap.innerHTML='<iframe loading="lazy" src="https://reactbits.dev/components/circular-gallery"></iframe>';
  wrap.classList.add("on");btn.textContent="סגור דמו";
});

